using ResourceLedger.Core;

public static class FeatureTests {
 public static void Register(Action<string,Action> test){
  void Yes(bool value){if(!value)throw new Exception("Expected true");}
  void Eq<T>(T expected,T actual){if(!EqualityComparer<T>.Default.Equals(expected,actual))throw new Exception($"Expected {expected}; actual {actual}");}
  test("Save payload is compressed and remains readable",()=>{var l=new Ledger();l.Observe("m","map",0,new Dictionary<string,long>{{"Rifle",3}});var payload=LedgerSerializer.Save(l);Yes(payload.StartsWith("RLZ1:",StringComparison.Ordinal));Yes(LedgerSerializer.TryLoad(payload,out var restored));Eq(3L,restored!.Series.Values.Single().Samples.Single().Count);});
  test("Previous plain JSON saves remain readable",()=>{Yes(LedgerSerializer.TryLoad("{\"Schema\":1,\"Tracked\":[\"Steel\"]}",out var restored));Eq("Steel",restored!.Tracked.Single());Yes(!LedgerSerializer.TryLoad("RLZ1:broken",out _));Yes(!LedgerSerializer.TryLoad("RLZ1:AAAA",out _));});
  test("Dual axes use independent readable steps",()=>{var stock=ChartMath.Scale(0,4200);var flow=ChartMath.Scale(-18,24);Eq(2000d,stock.Step);Eq(20d,flow.Step);Yes(stock.Min==0&&stock.Max>=4200&&flow.Min<=-18&&flow.Max>=24);});
  test("Zero and fractional scales stay finite",()=>{var zero=ChartMath.Scale(0,0);Yes(zero.Step>0&&double.IsFinite(zero.Step)&&zero.Max>zero.Min);var fraction=ChartMath.Scale(0,.034);Yes(fraction.Step<=.02&&fraction.Max>=.034);});
  test("Hourly and daily buckets preserve gross flows and ending stock",()=>{var s=new Series{Periods=new(){new Period{From=0,To=2500,Start=100,End=110,In=30,Out=20},new Period{From=2500,To=5000,Start=110,End=105,In=5,Out=10}}};var daily=ChartMath.Buckets(s,0,5000,60000).Single();Eq(105L,daily.Stock);Eq(35L,daily.Increase);Eq(30L,daily.Decrease);Yes(daily.Partial&&!daily.Gap);Eq(2,ChartMath.Buckets(s,0,5000,2500).Count);});
  test("Daily bucket gaps never become zero flows",()=>{var s=new Series{Periods=new(){new Period{From=0,To=2500,End=100},new Period{From=5000,To=7500,End=90,Out=10}}};Yes(ChartMath.Buckets(s,0,7500,60000).Single().Gap);});
  test("Initial stock is displayed without invented income",()=>{var s=new Series{Samples=new(){new Sample{Tick=1250,Count=1200}}};var point=ChartMath.Buckets(s,0,2500,2500).Single();Eq(1200L,point.Stock);Eq(0L,point.Increase);Yes(point.Gap&&point.Partial);});
  test("Discovery retains history and registers each type once",()=>{var ledger=new Ledger{Tracked=new(){"Steel"}};var added=ledger.Discover(new[]{"Rifle","Shirt","Rifle","Steel"});Eq(2,added.Count);Eq(3,ledger.Tracked.Count);ledger.Discover(Array.Empty<string>());Eq(3,ledger.Tracked.Count);});
  test("View filters do not remove tracked resources",()=>{var ledger=new Ledger{Tracked=new(){"Steel"}};var s=new Summary{Continuous=true,Increase=10,Decrease=10};Yes(ResourceSelection.Matches(ResourceVisibility.Changed,0,s));Yes(!ResourceSelection.Matches(ResourceVisibility.Owned,0,s));Yes(ResourceSelection.Matches(ResourceVisibility.History,0,s));Eq(1,ledger.Tracked.Count);Yes(!ResourceSelection.Matches(ResourceVisibility.Changed,1,new Summary{Continuous=false,Increase=10}));});
  test("New resource discovery preserves previous zero and known history",()=>{var l=new Ledger();l.Observe("m","map",0,new Dictionary<string,long>{{"Steel",10}});l.Discover(new[]{"Steel","Rifle"});l.EnsureBaseline("m","map",100,new Dictionary<string,long>{{"Steel",99}},l.Tracked);Eq(10L,l.Series[Ledger.Key("m","map","Steel")].Samples.Single().Count);Eq(0L,l.Series[Ledger.Key("m","map","Rifle")].Samples.Single().Count);l.Record(new LedgerEvent{Id="made",Map="m",Scope="map",Resource="Rifle",Tick=101,Delta=1,Cause=Cause.Production});l.Observe("m","map",2500,new Dictionary<string,long>{{"Rifle",2}});var sum=Queries.Summarize(l.Series[Ledger.Key("m","map","Rifle")],0,2500);Eq(2L,sum.Increase);Eq(1L,sum.Adjustment);});
  test("New custom scopes never inherit a backdated baseline",()=>{var l=new Ledger();var counts=new Dictionary<string,long>{{"Steel",10}};l.EnsureBaseline("m","new-scope",50,counts,new[]{"Steel"},historical:true);Eq(0,l.Series.Count);l.EnsureBaseline("m","new-scope",100,counts,new[]{"Steel"});Eq(100L,l.Series.Values.Single().Samples.Single().Tick);l.EnsureBaseline("m","map",50,counts,new[]{"Steel"},historical:true);Eq(50L,l.Series[Ledger.Key("m","map","Steel")].Samples.Single().Tick);});
  test("First captured acquisition uses a real zero baseline",()=>{var l=new Ledger();l.Discover(new[]{"Rifle"});l.Observe("m","map",100,new Dictionary<string,long>{{"Rifle",0}});l.Record(new LedgerEvent{Id="first",Map="m",Scope="map",Resource="Rifle",Tick=100,Delta=1,Cause=Cause.Production});l.Observe("m","map",2500,new Dictionary<string,long>{{"Rifle",1}});var summary=Queries.Summarize(l.Series.Values.Single(),0,2500);Eq(1L,summary.Increase);Eq(0L,summary.Adjustment);});
 }
}
